# Generated by Cursor (plan item 3: common acronym PhD)
"""Scan for common non-all-caps acronyms (PhD, Ph.D., etc.); emit (rule_id, start, span, path_str)."""

import re

# Allowlist: acronyms to spell letter-by-letter. Plan item 3.
COMMON_ACRONYM_WORDS = frozenset({"PhD", "Ph.D."})
# Word boundary match for these tokens
COMMON_ACRONYM_RE = re.compile(
    r"\b("
    + r"|".join(
        re.escape(w) for w in sorted(COMMON_ACRONYM_WORDS, key=len, reverse=True)
    )
    + r")\b"
)


def scan_turn_common_acronym(
    text: str,
    path_str: str = "",
) -> list[tuple[str, int, str, str]]:
    """Emit (common_acronym, start_index, span, path_str) for each allowlisted acronym."""
    result: list[tuple[str, int, str, str]] = []
    for m in COMMON_ACRONYM_RE.finditer(text):
        result.append(("common_acronym", m.start(), m.group(0), path_str))
    return result
